actions.script:
const levels = {CalpFreeBusy: 1, CalpView: 2, CalpEdit: 3, CalpManage: 4}
const names = [null, 'CalpFreeBusy', 'CalpView', 'CalpEdit', 'CalpManage']
const verbs = {CalpFreeBusy: 'see the free/busy times of', CalpView: 'view', CalpEdit: 'edit', CalpManage: 'manage'}
permissionMap = {}
isOwner = false
calendar = null
userPermissionEnumId = null
if (permissionEnumId && !levels[permissionEnumId]) { ec.message.addError(`Unknown calendar permission ${permissionEnumId}`); return }
const ids = []
if (calendarId) ids.push(calendarId)
if (calendarIdList) for (const id of Array.from(calendarIdList)) if (id && !ids.includes(id)) ids.push(id)
if (!ids.length) return
const cf = ec.entity.conditionFactory
const userId = ec.user.userId
const partyId = ec.user.userAccount?.partyId || null
const calendars = new Map()
for (const row of ec.entity.find('mantle.work.calendar.Calendar').condition(cf.makeCondition('calendarId', 'in', ids)).list())
    calendars.set(row.calendarId, row)
const level = new Map()
const owned = new Set()
if (userId) {
    for (const [id, row] of calendars) if (partyId && row.ownerPartyId === partyId) { level.set(id, 4); owned.add(id) }
    const shareIds = ids.filter((id) => calendars.has(id) && !owned.has(id))
    if (shareIds.length) {
        const groups = Array.from(ec.user.getUserGroupIdSet() || [])
        const orgIds = partyId ? Array.from(ec.entity.find('mantle.party.PartyRelationship').condition('fromPartyId', partyId)
                .condition(cf.makeCondition('relationshipTypeEnumId', 'in', ['PrtAgent', 'PrtEmployee', 'PrtMember']))
                .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('toPartyId').list())
                .map((row) => row.toPartyId) : []
        for (const share of ec.entity.find('mantle.work.calendar.CalendarShare').condition(cf.makeCondition('calendarId', 'in', shareIds))
                .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list()) {
            const applies = share.userId ? share.userId === userId
                    : share.userGroupId ? groups.includes(share.userGroupId)
                    : share.partyId ? (share.partyId === partyId || orgIds.includes(share.partyId)) : false
            if (applies) level.set(share.calendarId, Math.max(level.get(share.calendarId) || 0, levels[share.permissionEnumId] || 0))
        }
    }
}
for (const id of ids) permissionMap[id] = names[level.get(id) || 0]
if (!calendarId) return
const own = level.get(calendarId) || 0
const row = calendars.get(calendarId)
isOwner = owned.has(calendarId)
userPermissionEnumId = names[own]
calendar = own ? row.getMap() : null
if (!permissionEnumId) return
if (own === 0) { ec.message.addError(`Calendar ${calendarId} not found`); return }
if (own < levels[permissionEnumId])
    ec.message.addError(`You need permission to ${verbs[permissionEnumId]} the calendar ${row.calendarName || calendarId}`)

created = false
const partyId = ec.user.userAccount?.partyId
if (!ec.user.userId || !partyId) { ec.message.addError('A default calendar needs a user with a party'); return }
const personal = Array.from(ec.entity.find('mantle.work.calendar.Calendar').condition('ownerPartyId', partyId)
        .condition('calendarKindEnumId', 'CalkPersonal').orderBy('createdDate,calendarId').list())
const found = personal.find((row) => row.isDefault === 'Y') || personal[0]
if (found != null) {
    if (found.isDefault !== 'Y') { found.set('isDefault', 'Y'); found.update() }
    calendarId = found.calendarId
    return
}
let name = calendarName ? String(calendarName).trim() : ''
if (!name) {
    const person = ec.entity.find('mantle.party.Person').condition('partyId', partyId).one()
    name = person ? [person.firstName, person.lastName].filter((part) => part).join(' ') : ''
    if (!name) name = 'My Calendar'
}
calendarId = ec.service.sync().name('create#mantle.work.calendar.Calendar').parameters({calendarName: name,
    ownerPartyId: partyId, calendarKindEnumId: 'CalkPersonal', color: color || '#1e88e5', isDefault: 'Y',
    createdDate: ec.user.nowTimestamp}).call()?.calendarId
created = !ec.message.hasError()

const userId = ec.user.userId
const partyId = ec.user.userAccount?.partyId
if (!userId || !partyId) { ec.message.addError('Creating a calendar needs a user with a party'); return }
if (calendarKindEnumId === 'CalkSubscription') { ec.message.addError('A subscription calendar is made by subscribing to its feed'); return }
if (!['CalkPersonal', 'CalkShared', 'CalkResource'].includes(calendarKindEnumId)) {
    ec.message.addError(`Unknown calendar kind ${calendarKindEnumId}`); return }
if (!String(calendarName).trim()) { ec.message.addError('A calendar needs a name'); return }
const owner = ownerPartyId || partyId
if (calendarKindEnumId === 'CalkPersonal' && owner !== partyId) {
    ec.message.addError('A personal calendar belongs to its user; ownerPartyId is for a shared calendar'); return }
if (owner !== partyId) {
    // the owner as the user may see it
    const ownerParty = ec.entity.find('mantle.party.Party').condition('partyId', owner).one()
    if (ownerParty == null || ownerParty.privateOwnerUserId) { ec.message.addError(`Party ${owner} not found`); return }
}
const palette = ['#1e88e5', '#43a047', '#e53935', '#fb8c00', '#8e24aa', '#00897b', '#6d4c41', '#3949ab']
const fields = {calendarName: String(calendarName).trim(), description: description, calendarKindEnumId: calendarKindEnumId,
    timeZone: timeZone, ownerPartyId: owner, createdDate: ec.user.nowTimestamp, isDefault: 'N',
    color: color || palette[ec.entity.find('mantle.work.calendar.Calendar').condition('ownerPartyId', owner).count() % palette.length]}
if (calendarKindEnumId === 'CalkPersonal') {
    const personal = Array.from(ec.entity.find('mantle.work.calendar.Calendar').condition('ownerPartyId', owner)
            .condition('calendarKindEnumId', 'CalkPersonal').list())
    const makeDefault = isDefault === 'Y' || !personal.some((row) => row.isDefault === 'Y')
    if (makeDefault) for (const other of personal) if (other.isDefault === 'Y') { other.set('isDefault', 'N'); other.update() }
    fields.isDefault = makeDefault ? 'Y' : 'N'
}
calendarId = ec.service.sync().name('create#mantle.work.calendar.Calendar').parameters(fields).call()?.calendarId
if (ec.message.hasError()) return
if (owner !== partyId) {
    calendarShareId = ec.service.sync().name('create#mantle.work.calendar.CalendarShare').parameters({calendarId: calendarId,
        userId: userId, permissionEnumId: 'CalpManage', fromDate: ec.user.nowTimestamp}).call()?.calendarShareId
}

const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
        .parameters({calendarId: calendarId, permissionEnumId: 'CalpManage'}).call()
if (ec.message.hasError()) return
const row = ec.entity.find('mantle.work.calendar.Calendar').condition('calendarId', calendarId).one()
if (calendarName != null) {
    if (!String(calendarName).trim()) { ec.message.addError('A calendar needs a name'); return }
    row.set('calendarName', String(calendarName).trim())
}
if (description != null) row.set('description', description || null)
if (color != null) row.set('color', color || null)
if (timeZone != null) row.set('timeZone', timeZone || null)
if (isDefault != null && isDefault !== row.isDefault) {
    if (row.calendarKindEnumId !== 'CalkPersonal' || !access.isOwner) { ec.message.addError('Only your own personal calendar can be your default'); return }
    if (isDefault !== 'Y') { ec.message.addError('Make another calendar the default instead'); return }
    for (const other of ec.entity.find('mantle.work.calendar.Calendar').condition('ownerPartyId', row.ownerPartyId)
            .condition('calendarKindEnumId', 'CalkPersonal').condition('isDefault', 'Y').list()) {
        other.set('isDefault', 'N'); other.update()
    }
    row.set('isDefault', 'Y')
}
row.update()

removedEventCount = 0
cancelledEventCount = 0
const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
        .parameters({calendarId: calendarId, permissionEnumId: 'CalpManage'}).call()
if (ec.message.hasError()) return
const calendar = access.calendar
if (calendar.calendarKindEnumId === 'CalkPersonal' && calendar.isDefault === 'Y') {
    ec.message.addError('The default calendar cannot be deleted; make another calendar the default first'); return }
const cf = ec.entity.conditionFactory
const isFeed = calendar.calendarKindEnumId === 'CalkSubscription'
for (const row of ec.entity.find('mantle.work.calendar.CalendarWorkEffort').condition('calendarId', calendarId).list()) {
    if (isFeed && ec.entity.find('mantle.work.calendar.CalendarWorkEffort').condition('workEffortId', row.workEffortId)
            .condition(cf.makeCondition('calendarId', 'not-equals', calendarId)).count() === 0) {
        const event = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', row.workEffortId).one()
        if (event != null && event.statusId !== 'WeCancelled') { event.set('statusId', 'WeCancelled'); event.update(); cancelledEventCount++ }
    }
    row.delete()
    removedEventCount++
}
for (const share of ec.entity.find('mantle.work.calendar.CalendarShare').condition('calendarId', calendarId).list()) share.delete()
const subscription = ec.entity.find('mantle.work.calendar.CalendarSubscription').condition('calendarId', calendarId).one()
if (subscription != null) subscription.delete()
ec.entity.find('mantle.work.calendar.Calendar').condition('calendarId', calendarId).one().delete()

const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
        .parameters({calendarId: calendarId, permissionEnumId: 'CalpManage'}).call()
if (ec.message.hasError()) return
const calendar = access.calendar
if (!['CalpFreeBusy', 'CalpView', 'CalpEdit', 'CalpManage'].includes(permissionEnumId)) {
    ec.message.addError(`Unknown calendar permission ${permissionEnumId}`); return }
const cf = ec.entity.conditionFactory
const now = ec.user.nowTimestamp
const current = Array.from(ec.entity.find('mantle.work.calendar.CalendarShare').condition('calendarId', calendarId)
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
if (publish) {
    if (userId || userGroupId || partyId) {
        ec.message.addError('A publish link is for anyone with the link; share with a user, group or party apart from it'); return }
    if (!['CalpFreeBusy', 'CalpView'].includes(permissionEnumId)) { ec.message.addError('A publish link gives view or free/busy only'); return }
    const existing = current.find((share) => share.publishToken && !share.userId && !share.userGroupId && !share.partyId)
    const hash = password == null ? undefined : (String(password) ? ec.user.hashPassword(String(password)) : null)
    if (existing != null) {
        existing.set('permissionEnumId', permissionEnumId)
        existing.set('thruDate', thruDate)
        if (hash !== undefined) existing.set('passwordHash', hash)
        if (newToken) existing.set('publishToken', ec.user.randomString(40))
        existing.update()
        calendarShareId = existing.calendarShareId
        publishToken = existing.publishToken
        return
    }
    publishToken = ec.user.randomString(40)
    calendarShareId = ec.service.sync().name('create#mantle.work.calendar.CalendarShare').parameters({calendarId: calendarId,
        permissionEnumId: permissionEnumId, publishToken: publishToken, passwordHash: hash ?? null, fromDate: now,
        thruDate: thruDate}).call()?.calendarShareId
    return
}
if ([userId, userGroupId, partyId].filter((value) => value).length !== 1) {
    ec.message.addError('Share a calendar with one user, user group or party'); return }
if (userId) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()
    if (account == null) { ec.message.addError(`User ${userId} not found`); return }
    if (account.partyId && account.partyId === calendar.ownerPartyId) { ec.message.addError('That user owns the calendar'); return }
}
if (userGroupId && ec.entity.find('moqui.security.UserGroup').condition('userGroupId', userGroupId).one() == null) {
    ec.message.addError(`User group ${userGroupId} not found`); return }
if (partyId) {
    const party = ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()
    if (party == null || party.privateOwnerUserId) { ec.message.addError(`Party ${partyId} not found`); return }
    // the owner's person manages already; an organization that owns a calendar may still open it to its people
    if (partyId === calendar.ownerPartyId && ec.entity.find('moqui.security.UserAccount').condition('partyId', partyId)
            .disableAuthz().count() > 0) { ec.message.addError('That party owns the calendar'); return }
}
const existing = current.find((share) => userId ? share.userId === userId : userGroupId ? share.userGroupId === userGroupId
        : share.partyId === partyId)
if (existing != null) {
    const ownerHasUser = calendar.ownerPartyId && ec.entity.find('moqui.security.UserAccount')
            .condition('partyId', calendar.ownerPartyId).disableAuthz().count() > 0
    if (!ownerHasUser && existing.permissionEnumId === 'CalpManage' && permissionEnumId !== 'CalpManage'
            && !current.some((share) => share !== existing && share.permissionEnumId === 'CalpManage' && !share.publishToken)) {
        ec.message.addError('A calendar an organization owns keeps at least one manage share'); return }
    existing.set('permissionEnumId', permissionEnumId)
    existing.set('thruDate', thruDate)
    existing.update()
    calendarShareId = existing.calendarShareId
    return
}
calendarShareId = ec.service.sync().name('create#mantle.work.calendar.CalendarShare').parameters({calendarId: calendarId,
    userId: userId, userGroupId: userGroupId, partyId: partyId, permissionEnumId: permissionEnumId, fromDate: now,
    thruDate: thruDate}).call()?.calendarShareId

unsharedCount = 0
const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
        .parameters({calendarId: calendarId, permissionEnumId: 'CalpManage'}).call()
if (ec.message.hasError()) return
if (!calendarShareId && !userId && !userGroupId && !partyId && !publish) {
    ec.message.addError('Name the share, user, user group or party to unshare'); return }
const cf = ec.entity.conditionFactory
const current = Array.from(ec.entity.find('mantle.work.calendar.CalendarShare').condition('calendarId', calendarId)
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
const ending = current.filter((share) => (calendarShareId && share.calendarShareId === calendarShareId)
        || (userId && share.userId === userId) || (userGroupId && share.userGroupId === userGroupId)
        || (partyId && share.partyId === partyId) || (publish && share.publishToken && !share.userId && !share.userGroupId && !share.partyId))
const owner = access.calendar.ownerPartyId
const ownerHasUser = owner && ec.entity.find('moqui.security.UserAccount').condition('partyId', owner).disableAuthz().count() > 0
const managersLeft = current.filter((share) => !ending.includes(share) && share.permissionEnumId === 'CalpManage' && !share.publishToken).length
if (!ownerHasUser && managersLeft === 0 && ending.some((share) => share.permissionEnumId === 'CalpManage' && !share.publishToken)) {
    ec.message.addError('A calendar an organization owns keeps at least one manage share'); return }
for (const share of ending) { share.set('thruDate', ec.user.nowTimestamp); share.update(); unsharedCount++ }

calendarList = []
defaultCalendarId = null
const userId = ec.user.userId
const partyId = ec.user.userAccount?.partyId
if (!userId || !partyId) return
if (ensureDefault) {
    defaultCalendarId = ec.service.sync().name('mantle.work.CalendarServices.ensure#UserDefaultCalendar').call()?.calendarId || null
    if (ec.message.hasError()) return
}
const cf = ec.entity.conditionFactory
const owned = Array.from(ec.entity.find('mantle.work.calendar.Calendar').condition('ownerPartyId', partyId).list())
const groups = Array.from(ec.user.getUserGroupIdSet() || [])
const orgIds = Array.from(ec.entity.find('mantle.party.PartyRelationship').condition('fromPartyId', partyId)
        .condition(cf.makeCondition('relationshipTypeEnumId', 'in', ['PrtAgent', 'PrtEmployee', 'PrtMember']))
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('toPartyId').list()).map((row) => row.toPartyId)
const shareTargets = [cf.makeCondition('userId', 'equals', userId), cf.makeCondition('partyId', 'in', [partyId].concat(orgIds))]
if (groups.length) shareTargets.push(cf.makeCondition('userGroupId', 'in', groups))
const ownedIds = new Set(owned.map((row) => row.calendarId))
const sharedIds = Array.from(new Set(Array.from(ec.entity.find('mantle.work.calendar.CalendarShare').condition(cf.makeCondition(shareTargets, 'or'))
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('calendarId').list())
        .map((row) => row.calendarId).filter((id) => !ownedIds.has(id))))
const shared = sharedIds.length ? Array.from(ec.entity.find('mantle.work.calendar.Calendar')
        .condition(cf.makeCondition('calendarId', 'in', sharedIds)).list()) : []
const access = shared.length ? ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
        .parameters({calendarIdList: sharedIds}).call() : {permissionMap: {}}
if (ec.message.hasError()) return
const ownerNames = new Map()
const ownerName = (id) => {
    if (!id) return null
    if (!ownerNames.has(id)) {
        const detail = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
        ownerNames.set(id, detail ? (detail.organizationName || [detail.firstName, detail.lastName].filter((part) => part).join(' ') || id) : id)
    }
    return ownerNames.get(id)
}
const entryOf = (row, permission, isOwner, group) => {
    const entry = {calendarId: row.calendarId, calendarName: row.calendarName, description: row.description ?? null,
        color: row.color ?? null, calendarKindEnumId: row.calendarKindEnumId, timeZone: row.timeZone ?? null,
        isDefault: row.isDefault === 'Y', ownerPartyId: row.ownerPartyId ?? null, ownerName: ownerName(row.ownerPartyId),
        permissionEnumId: permission, isOwner: isOwner, group: group, shareCount: 0, hasPublishLink: false, subscription: null}
    if (permission === 'CalpManage') {
        const shares = Array.from(ec.entity.find('mantle.work.calendar.CalendarShare').condition('calendarId', row.calendarId)
                .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
        entry.shareCount = shares.filter((share) => share.userId || share.userGroupId || share.partyId).length
        entry.hasPublishLink = shares.some((share) => share.publishToken && !share.userId && !share.userGroupId && !share.partyId)
    }
    if (row.calendarKindEnumId === 'CalkSubscription') {
        const subscription = ec.entity.find('mantle.work.calendar.CalendarSubscription').condition('calendarId', row.calendarId).one()
        if (subscription != null) entry.subscription = {url: subscription.url ?? null, providerEnumId: subscription.providerEnumId ?? null,
            refreshMinutes: subscription.refreshMinutes ?? null, lastFetchDate: subscription.lastFetchDate ?? null,
            lastFetchStatus: subscription.lastFetchStatus ?? null, lastFetchError: subscription.lastFetchError ?? null}
    }
    return entry
}
const byName = (a, b) => String(a.calendarName || '').localeCompare(String(b.calendarName || ''))
const mine = owned.filter((row) => row.calendarKindEnumId !== 'CalkSubscription').map((row) => entryOf(row, 'CalpManage', true, 'mine'))
        .sort((a, b) => (a.isDefault ? 0 : 1) - (b.isDefault ? 0 : 1) || byName(a, b))
const subscriptions = owned.filter((row) => row.calendarKindEnumId === 'CalkSubscription')
        .map((row) => entryOf(row, 'CalpManage', true, 'subscription')).sort(byName)
const others = shared.filter((row) => access.permissionMap[row.calendarId])
        .map((row) => entryOf(row, access.permissionMap[row.calendarId], false, 'shared')).sort(byName)
calendarList = mine.concat(subscriptions, others)
if (!defaultCalendarId) defaultCalendarId = mine.find((entry) => entry.isDefault)?.calendarId || null

added = false
const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
        .parameters({calendarId: calendarId, permissionEnumId: 'CalpEdit'}).call()
if (ec.message.hasError()) return
if (access.calendar.calendarKindEnumId === 'CalkSubscription') {
    ec.message.addError('The events of a subscription calendar come from its feed'); return }
ec.service.sync().name('mantle.work.EventServices.check#EventAccess').parameters({workEffortId: workEffortId}).call()
if (ec.message.hasError()) return
if (ec.entity.find('mantle.work.calendar.CalendarWorkEffort').condition('calendarId', calendarId)
        .condition('workEffortId', workEffortId).one() != null) return
ec.service.sync().name('create#mantle.work.calendar.CalendarWorkEffort').parameters({calendarId: calendarId,
    workEffortId: workEffortId, addedDate: ec.user.nowTimestamp}).call()
added = !ec.message.hasError()

removed = false
const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
        .parameters({calendarId: calendarId, permissionEnumId: 'CalpEdit'}).call()
if (ec.message.hasError()) return
if (access.calendar.calendarKindEnumId === 'CalkSubscription') {
    ec.message.addError('The events of a subscription calendar come from its feed'); return }
const row = ec.entity.find('mantle.work.calendar.CalendarWorkEffort').condition('calendarId', calendarId)
        .condition('workEffortId', workEffortId).one()
if (row == null) return
row.delete()
removed = true

const partyId = ec.user.userAccount?.partyId
if (!ec.user.userId || !partyId) { ec.message.addError('A calendar subscription needs a user with a party'); return }
if (providerEnumId === 'CspGoogle' || providerEnumId === 'CspMicrosoft') {
    ec.message.addError('Subscribing to a Google or Microsoft 365 account is not available yet'); return }
if (providerEnumId !== 'CspIcsUrl') { ec.message.addError(`Unknown calendar provider ${providerEnumId}`); return }
const text = url ? String(url).trim() : ''
const match = /^(https?|webcal):\/\/([^\/?#:]+)/i.exec(text)
if (!match) { ec.message.addError('A calendar subscription needs an http, https or webcal URL'); return }
const minutes = Math.max(5, Number(refreshMinutes) || 60)
calendarId = ec.service.sync().name('create#mantle.work.calendar.Calendar').parameters({
    calendarName: calendarName ? String(calendarName).trim() : match[2], ownerPartyId: partyId,
    calendarKindEnumId: 'CalkSubscription', color: color || '#757575', isDefault: 'N',
    createdDate: ec.user.nowTimestamp}).call()?.calendarId
if (ec.message.hasError()) return
ec.service.sync().name('create#mantle.work.calendar.CalendarSubscription').parameters({calendarId: calendarId,
    url: text, providerEnumId: providerEnumId, refreshMinutes: minutes}).call()
if (ec.message.hasError()) return
if (fetchNow) ec.service.async().name('mantle.work.CalendarServices.fetch#CalendarSubscriptions')
        .parameters({calendarId: calendarId, force: true}).call()

fetchedCount = 0
failedCount = 0
// the job (authorization disabled) fetches them all; a user only a calendar they manage
if (!ec.artifactExecution.authzDisabled()) {
    if (!calendarId) { ec.message.addError('Name the subscription calendar to fetch (calendarId)'); return }
    ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess').parameters({calendarId: calendarId,
        permissionEnumId: 'CalpManage'}).call()
    if (ec.message.hasError()) return
}
toolAvailable = ec.factory.getToolFactory('ICalendar') != null
if (!toolAvailable) {
    let logged = false
    try {
        const notices = ec.cache.getCache('mantle.work.calendar.notices')
        logged = !!notices.get('fetchNoTool')
        if (!logged) notices.put('fetchNoTool', true)
    } catch (err) { logged = false }
    if (!logged) ec.logger.info('Calendar subscriptions are not fetched: the framework ICalendar tool is not available')
    return
}
const toMillis = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
const nowMillis = toMillis(ec.user.nowTimestamp)
let find = ec.entity.find('mantle.work.calendar.CalendarSubscription').condition('providerEnumId', 'CspIcsUrl')
if (calendarId) find = find.condition('calendarId', calendarId)
for (const subscription of Array.from(find.list())) {
    const last = toMillis(subscription.lastFetchDate)
    if (!force && last != null && last + (Number(String(subscription.refreshMinutes ?? 60)) || 60) * 60000 > nowMillis) continue
    let error = null
    try {
        ec.service.sync().name('mantle.work.CalendarServices.fetch#CalendarSubscription')
                .parameters({calendarId: subscription.calendarId}).requireNewTransaction(true).call()
        if (ec.message.hasError()) error = ec.message.getErrorsString()
    } catch (err) {
        error = String(err && err.message ? err.message : err)
    }
    if (error) {
        ec.message.clearErrors()
        failedCount++
        ec.logger.error(`Calendar subscription ${subscription.calendarId} (${subscription.url}) not fetched: ${error}`)
        try {
            ec.service.sync().name('update#mantle.work.calendar.CalendarSubscription').parameters({calendarId: subscription.calendarId,
                lastFetchDate: ec.user.nowTimestamp, lastFetchStatus: 'error', lastFetchError: error.substring(0, 4000)})
                    .requireNewTransaction(true).call()
        } catch (err) { ec.logger.error(`Calendar subscription ${subscription.calendarId} status not saved: ${err}`) }
        ec.message.clearErrors()
    } else {
        fetchedCount++
    }
}

if (!ec.artifactExecution.authzDisabled()) {
    ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess').parameters({calendarId: calendarId,
        permissionEnumId: 'CalpManage'}).call()
    if (ec.message.hasError()) return
}
const subscription = ec.entity.find('mantle.work.calendar.CalendarSubscription').condition('calendarId', calendarId).one()
if (subscription == null || !subscription.url) { ec.message.addError(`Calendar subscription ${calendarId} not found`); return }
if (ec.factory.getToolFactory('ICalendar') == null) { ec.message.addError('The ICalendar tool is not available'); return }
const uri = String(subscription.url).replace(/^webcal:/i, 'https:')
const response = ec.service.rest().method('GET').uri(uri).contentType('text/calendar').timeout(60).call()
const status = response.getStatusCode()
if (status < 200 || status >= 300) { ec.message.addError(`The feed answered ${status} ${response.getReasonPhrase() || ''}`.trim()); return }
const feedText = response.text()
if (!feedText || !String(feedText).trim()) { ec.message.addError('The feed answered with no calendar'); return }
const stored = ec.service.sync().name('mantle.work.CalendarServices.store#CalendarFeedText')
        .parameters({calendarId: calendarId, feedText: feedText}).call()
if (ec.message.hasError()) return
createdCount = stored.createdCount; updatedCount = stored.updatedCount; removedCount = stored.removedCount

const subscription = ec.entity.find('mantle.work.calendar.CalendarSubscription').condition('calendarId', calendarId).one()
if (subscription == null) { ec.message.addError(`Calendar subscription ${calendarId} not found`); return }
if (ec.factory.getToolFactory('ICalendar') == null) { ec.message.addError('The ICalendar tool is not available'); return }
const parsed = ec.factory.getTool('ICalendar').parse(String(feedText))
const events = Array.from(parsed?.events || [])
const stored = ec.service.sync().name('mantle.work.CalendarServices.store#CalendarFeedEvents')
        .parameters({calendarId: calendarId, eventList: events, replaceAll: true}).call()
if (ec.message.hasError()) return
createdCount = stored.createdCount; updatedCount = stored.updatedCount; removedCount = stored.removedCount
failedCount = stored.failedCount
subscription.set('lastFetchDate', ec.user.nowTimestamp)
subscription.set('lastFetchStatus', stored.failedCount ? 'error' : 'ok')
subscription.set('lastFetchError', stored.failedCount ? `${stored.failedCount} of ${events.length} events not read` : null)
subscription.update()

createdCount = 0; updatedCount = 0; removedCount = 0; failedCount = 0
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
const dayBefore = (text) => {
    const [y, m, d] = String(text).substring(0, 10).split('-').map(Number)
    return new Date(Date.UTC(y, m - 1, d - 1)).toISOString().substring(0, 10)
}
const statusOf = {CONFIRMED: 'WeApproved', TENTATIVE: 'WeInPlanning', CANCELLED: 'WeCancelled'}
const listText = (list) => list == null ? null : (Array.isArray(list) || typeof list === 'object' ? Array.from(list).join(',') : String(list)) || null
// the calendar's current events by UID: the series (no instance link) and the overrides by series and recurrence
const existing = Array.from(ec.entity.find('mantle.work.calendar.CalendarWorkEffortDetail').condition('calendarId', calendarId).list())
const existingIds = existing.map((row) => row.workEffortId)
const instanceLinks = existingIds.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc')
        .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').condition(cf.makeCondition('toWorkEffortId', 'in', existingIds)).list()) : []
const linkOf = new Map(instanceLinks.map((link) => [link.toWorkEffortId, link]))
const seriesByUid = new Map()
const overrideByKey = new Map()
for (const row of existing) {
    if (!row.universalId) continue
    const link = linkOf.get(row.workEffortId)
    if (link) overrideByKey.set(`${row.universalId}|${toMillis(link.fromDate)}`, row.workEffortId)
    else seriesByUid.set(row.universalId, row.workEffortId)
}
const seenIds = new Set()
const fieldsOf = (event) => {
    const fields = {workEffortName: event.summary || '(no title)', description: event.description ?? null,
        location: event.location ?? null, infoUrl: event.url ?? null, statusId: statusOf[String(event.status || 'CONFIRMED').toUpperCase()] || 'WeApproved',
        workEffortTypeEnumId: 'WetEvent', timeUomId: 'TF_hr', revisionNumber: event.sequence ?? null,
        estimatedStartDate: null, estimatedCompletionDate: null, allDayStart: null, allDayEnd: null}
    if (event.allDay) {
        const startDay = String(event.startDate || '').substring(0, 10)
        if (!/^\d{4}-\d{2}-\d{2}$/.test(startDay)) throw new Error('an all-day event without its start date')
        fields.allDayStart = startDay
        const endDay = event.endDate ? dayBefore(event.endDate) : null
        fields.allDayEnd = endDay && endDay > startDay ? endDay : null
    } else {
        const start = toMillis(event.start)
        if (start == null || Number.isNaN(start)) throw new Error('an event without its start')
        fields.estimatedStartDate = new Date(start)
        const end = toMillis(event.end)
        fields.estimatedCompletionDate = end == null || Number.isNaN(end) ? null : new Date(end)
    }
    return fields
}
const storeRecurrence = (workEffortId, event) => {
    const row = ec.entity.find('mantle.work.effort.WorkEffortRecurrence').condition('workEffortId', workEffortId).one()
    if (!event.rrule && !event.rdates?.length) { if (row != null) row.delete(); return }
    const fields = {rrule: event.rrule ?? null, exdates: listText(event.exdates), rdates: listText(event.rdates), timeZone: event.timeZone ?? null}
    if (row == null) ec.service.sync().name('create#mantle.work.effort.WorkEffortRecurrence').parameters(Object.assign({workEffortId: workEffortId}, fields)).call()
    else { for (const [field, value] of Object.entries(fields)) row.set(field, value); row.update() }
}
const upsert = (workEffortId, fields) => {
    if (workEffortId) {
        const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
        for (const [field, value] of Object.entries(fields)) row.set(field, value)
        row.update()
        updatedCount++
        return workEffortId
    }
    const id = ec.service.sync().name('create#mantle.work.effort.WorkEffort').parameters(fields).call()?.workEffortId
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    ec.service.sync().name('create#mantle.work.calendar.CalendarWorkEffort').parameters({calendarId: calendarId,
        workEffortId: id, addedDate: ec.user.nowTimestamp}).call()
    createdCount++
    return id
}
// the series first, then the overrides, which need their series
const events = Array.from(eventList || [])
const ordered = events.filter((event) => event && event.recurrenceId == null).concat(events.filter((event) => event && event.recurrenceId != null))
for (const event of ordered) {
    ec.message.pushErrors()
    try {
        if (!event.uid) throw new Error('an event without a UID')
        const uid = String(event.uid)
        const fields = Object.assign(fieldsOf(event), {universalId: uid})
        if (event.recurrenceId == null) {
            const id = upsert(seriesByUid.get(uid), fields)
            seriesByUid.set(uid, id)
            storeRecurrence(id, event)
            seenIds.add(id)
        } else {
            const seriesId = seriesByUid.get(uid)
            if (!seriesId) throw new Error(`an instance of ${uid} without its series`)
            const recurrenceMillis = toMillis(event.recurrenceId)
            const key = `${uid}|${recurrenceMillis}`
            const known = overrideByKey.get(key)
            const id = upsert(known, fields)
            if (!known) ec.service.sync().name('create#mantle.work.effort.WorkEffortAssoc').parameters({workEffortId: seriesId,
                toWorkEffortId: id, workEffortAssocTypeEnumId: 'WeatRecurrenceInstance', fromDate: new Date(recurrenceMillis)}).call()
            overrideByKey.set(key, id)
            seenIds.add(id)
        }
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        failedCount++
        ec.logger.warn(`Calendar ${calendarId} feed event ${event?.uid || '(no UID)'} not stored: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
if (!replaceAll) return
for (const row of existing) {
    if (seenIds.has(row.workEffortId)) continue
    const link = ec.entity.find('mantle.work.calendar.CalendarWorkEffort').condition('calendarId', calendarId)
            .condition('workEffortId', row.workEffortId).one()
    if (link != null) link.delete()
    const event = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', row.workEffortId).one()
    if (event != null && event.statusId !== 'WeCancelled') { event.set('statusId', 'WeCancelled'); event.update() }
    removedCount++
}

const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
        .parameters({calendarId: calendarId, permissionEnumId: 'CalpView'}).call()
if (ec.message.hasError()) return
if (access.userPermissionEnumId === 'CalpFreeBusy') { ec.message.addError('You need permission to view the calendar to export it'); return }
if (ec.factory.getToolFactory('ICalendar') == null) { ec.message.addError('Calendar export is not available yet'); return }
const ids = Array.from(ec.entity.find('mantle.work.calendar.CalendarWorkEffortDetail').condition('calendarId', calendarId)
        .condition(ec.entity.conditionFactory.makeCondition('statusId', 'not-equals', 'WeCancelled', true))
        .selectField('workEffortId').list()).map((row) => row.workEffortId)
const events = ids.length ? (ec.service.sync().name('mantle.work.EventServices.get#EventIcsMaps')
        .parameters({workEffortIdList: ids}).call()?.eventMapList || []) : []
if (ec.message.hasError()) return
fileText = ec.factory.getTool('ICalendar').write({method: 'PUBLISH', calendarName: access.calendar.calendarName,
    timeZone: access.calendar.timeZone || ec.user.timeZone, events: events})
fileName = `${String(access.calendar.calendarName || calendarId).replace(/[^A-Za-z0-9 _.-]/g, '_')}.ics`
contentType = 'text/calendar'

const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
        .parameters({calendarId: calendarId, permissionEnumId: 'CalpEdit'}).call()
if (ec.message.hasError()) return
if (access.calendar.calendarKindEnumId === 'CalkSubscription') { ec.message.addError('The events of a subscription calendar come from its feed'); return }
if (ec.factory.getToolFactory('ICalendar') == null) { ec.message.addError('Calendar import is not available yet'); return }
const text = fileText || (calendarFile ? calendarFile.getString('UTF-8') : null)
if (!text) { ec.message.addError('No calendar file to import'); return }
const parsed = ec.factory.getTool('ICalendar').parse(text)
const stored = ec.service.sync().name('mantle.work.CalendarServices.store#CalendarFeedEvents')
        .parameters({calendarId: calendarId, eventList: Array.from(parsed?.events || []), replaceAll: false}).call()
if (ec.message.hasError()) return
createdCount = stored.createdCount; updatedCount = stored.updatedCount; failedCount = stored.failedCount
